const p=await figma.getNodeByIdAsync('13:4130');await figma.setCurrentPageAsync(p);const changed=[];const close={trigger:{type:'ON_CLICK'},actions:[{type:'CLOSE'}]};for(const m of p.children.filter(n=>n.type==='FRAME'&&/^(09|1[0-5])/.test(n.name))){const heading=m.children.find(n=>n.name==='Dialog heading');const x=heading?.findOne(n=>n.type==='INSTANCE'&&n.name==='Icon / xmark');if(x){await x.setReactionsAsync([close]);changed.push(x.id);}for(const b of m.findAll(n=>n.type==='INSTANCE'&&n.name==='Calla/Button')){const label=b.findOne(n=>n.type==='TEXT')?.characters;if(label==='취소'){await b.setReactionsAsync([close]);changed.push(b.id);}}}for(const [id,label,destination]of [['13:7739','이미지 설정','13:7862'],['13:7862','기본 설정','13:7739']]){const m=await figma.getNodeByIdAsync(id);const tab=m.findOne(n=>n.type==='INSTANCE'&&n.name==='Calla/Tab'&&n.findOne(t=>t.type==='TEXT'&&t.characters===label));if(tab){await tab.setReactionsAsync([{trigger:{type:'ON_CLICK'},actions:[{type:'NODE',destinationId:destination,navigation:'SWAP',transition:null}]}]);changed.push(tab.id);}}const request=await figma.getNodeByIdAsync('13:5873');p.selection=[request];figma.viewport.scrollAndZoomIntoView([request]);return {changedNodeIds:changed,overlays:p.children.filter(n=>n.type==='FRAME'&&/^(09|1[0-5])/.test(n.name)).map(n=>({id:n.id,position:n.overlayPositionType})),prototypeLinks:p.findAll(n=>'reactions'in n&&n.reactions.length>0).length};
